/* Full-text search for the docsify site.
 * Index (search-index.json) is generated by scripts/gen.py in CI.
 * Search box is injected at the top of the sidebar.
 *
 * The index (~1MB of plain text) is fetched lazily on first use instead of on
 * every page load, and cached in localStorage keyed by the index version so it
 * is only re-parsed when the content actually changes.
 *
 * Pure substring matching works naturally for CJK (no tokenizer).
 */
(function () {
  'use strict'

  var INDEX_URL = 'search-index.json'
  var MAX_RESULTS = 20
  var LS_KEY = 'memo-search-index-v1'
  var docs = []
  var loading = false
  var pendingQuery = null
  var indexUrl = 'search-index.json'

  function countOccurrences(text, term) {
    var count = 0
    var idx = text.indexOf(term)
    while (idx !== -1) {
      count++
      idx = text.indexOf(term, idx + term.length)
    }
    return count
  }

  function snippet(text, q) {
    var i = text.indexOf(q)
    if (i < 0) {
      return text.slice(0, 80) + (text.length > 80 ? '…' : '')
    }
    var start = Math.max(0, i - 30)
    var end = Math.min(text.length, i + q.length + 40)
    return (
      (start > 0 ? '…' : '') +
      text.slice(start, end).replace(/\n/g, ' ') +
      (end < text.length ? '…' : '')
    )
  }

  function pathToHref(path) {
    return '#/' + path.replace(/\.md$/, '').replace(/ /g, '%20')
  }

  function runSearch(rawQuery) {
    var list = document.getElementById('search-results')
    if (!list) return
    list.innerHTML = ''

    var terms = rawQuery.toLowerCase().split(/\s+/).filter(Boolean)
    if (!terms.length) return

    var scored = []
    for (var d = 0; d < docs.length; d++) {
      var doc = docs[d]
      var text = (doc.text || '').toLowerCase()
      var title = (doc.title || '').toLowerCase()
      var score = 0
      var ok = true
      for (var t = 0; t < terms.length; t++) {
        var term = terms[t]
        var hits = countOccurrences(text, term)
        if (!hits) {
          ok = false
          break
        }
        score += hits + (title.indexOf(term) !== -1 ? 20 : 0)
      }
      if (ok) {
        scored.push({ doc: doc, score: score })
      }
    }

    scored.sort(function (a, b) {
      return b.score - a.score
    })

    scored.slice(0, MAX_RESULTS).forEach(function (item) {
      var a = document.createElement('a')
      a.href = pathToHref(item.doc.path)
      a.className = 'search-result'
      var title = document.createElement('div')
      title.className = 'search-result-title'
      title.textContent = item.doc.title
      var body = document.createElement('div')
      body.className = 'search-result-snippet'
      body.textContent = snippet(item.doc.text, rawQuery)
      a.appendChild(title)
      a.appendChild(body)
      list.appendChild(a)
    })
  }

  function readCache() {
    try {
      var data = JSON.parse(localStorage.getItem(LS_KEY) || 'null')
      if (data && Array.isArray(data.docs)) {
        return data
      }
    } catch (e) {}
    return null
  }

  function writeCache(version, docsArr) {
    try {
      localStorage.setItem(
        LS_KEY,
        JSON.stringify({ version: version || '', docs: docsArr })
      )
    } catch (e) {}
  }

  // Fetch the index on first use, then run the pending query.
  function ensureIndex(query) {
    if (docs.length) {
      runSearch(query)
      return
    }
    pendingQuery = query
    if (loading) return
    loading = true

    fetch(indexUrl)
      .then(function (res) {
        return res.json()
      })
      .then(function (data) {
        // search-index.json is served with Cache-Control: no-cache, so this
        // fetch revalidates cheaply (304) and data.version reflects the
        // current build even when the body comes from the HTTP cache.
        var cached = readCache()
        if (cached && data.version && cached.version === data.version) {
          docs = cached.docs
        } else {
          docs = data.docs || []
          writeCache(data.version, docs)
        }
      })
      .catch(function () {
        var cached = readCache()
        if (cached) {
          docs = cached.docs
        }
      })
      .then(function () {
        loading = false
        if (pendingQuery) {
          var q = pendingQuery
          pendingQuery = null
          runSearch(q)
        }
      })
  }

  window.SearchPlugin = function (hook, vm) {
    hook.afterEach(function (html) {
      return html.replace(
        /<img(?![^>]*loading=)/gi,
        '<img loading="lazy" decoding="async"'
      )
    })

    hook.ready(function () {
      var base = vm.config.basePath || '/'
      indexUrl = base.replace(/\/$/, '') + '/' + INDEX_URL

      var sidebar = document.querySelector('.sidebar')
      if (!sidebar) return

      var box = document.createElement('div')
      box.className = 'search-box'
      box.innerHTML = '<input type="text" placeholder="全文搜索…">'
      var results = document.createElement('div')
      results.id = 'search-results'
      results.className = 'search-results'
      box.appendChild(results)
      sidebar.insertBefore(box, sidebar.firstChild)

      var input = box.querySelector('input')
      var timer = null
      input.addEventListener('focus', function () {
        if (input.value.trim()) {
          ensureIndex(input.value.trim())
        }
      })
      input.addEventListener('input', function () {
        clearTimeout(timer)
        timer = setTimeout(function () {
          var q = input.value.trim()
          if (!q) {
            runSearch('')
            return
          }
          ensureIndex(q)
        }, 150)
      })
    })
  }
})()
